      "availability": "SOURCE_SUPPORTED",
      "literal_kind": "verbal",
      "instructional_role": null,
      "refs": ["Q0009", "Q0010", "Q0011"],
      "related_refs": []
    },
    {
      "id": "C4",
      "text": "Common access modifiers are public, private, and so on.",
