      "instructional_role": null,
      "refs": ["Q0013"],
      "related_refs": []
    },
    {
      "id": "C5",
      "text": "The public access modifier is commonly used and placed before class and method declarations.",
      "basis": "explicit",
      "availability": "SOURCE_SUPPORTED",
      "literal_kind": "verbal",
      "instructional_role": null,
      "refs": ["Q0015", "Q0016"],
      "related_refs": []
    },
    {
      "id": "C6",
      "text": "Java naming convention uses PascalCase for class names.",
